package net.flashlight.battery;import fixture.Checks;public class ToggleChecks7{public static class Player extends Checks.Player{public boolean isAlive(){return true;}public boolean isSpectator(){return false;}}public static void main(String[]a){int n=0;for(String t:Power.TYPES){var p=new Player();p.main=(net.minecraft.world.item.ItemStack)Power.stack("flashlight:"+t+"_off");Power.charge(p.main,42);Power.toggle(p);if(!Power.on(p.main)||Power.remaining(p.main)!=42)throw new AssertionError("keyboard recognizes tier and keeps battery");n++;Power.toggle(p);if(Power.on(p.main)||Power.remaining(p.main)!=42)throw new AssertionError("keyboard turns off same tier");n++;}System.out.println("KEYBOARD_ALL_TIER_TOGGLE_BATTERY_PRESERVATION_CHECKS="+n);}}
